static void journey_rect(float x,float y,float w,float h,int r,int gg,int b,int a){SDL_SetRenderDrawColor(renderer,r,gg,b,a);SDL_FRect d={x*3,y*3,w*3,h*3};SDL_RenderFillRect(renderer,&d);}
static void journey_line(float x,float y,float xx,float yy,int r,int gg,int b,int a){SDL_SetRenderDrawColor(renderer,r,gg,b,a);SDL_RenderLine(renderer,x*3,y*3,xx*3,yy*3);}
static void journey_cell(SDL_Texture*t,int col,int row,int cols,int rows,float x,float y,float w,float h){nquad=0;quad((x-w/2)*3,(y-h/2)*3,w*3,h*3,(SDL_FColor){1,1,1,1},col/(float)cols,row/(float)rows,1.0f/cols,1.0f/rows);flush(t);}
static int journey_plate(void){switch(journey_kind()){case ENV_OCEAN:return 0;case ENV_WRECK:return 1;case ENV_HIVE:case ENV_ROOT:return 2;case ENV_BEAST:case ENV_TEETH:return 3;case ENV_BASE:case ENV_REACTOR:case ENV_ESCAPE:return 4;case ENV_ICE:case ENV_BLIZZARD:return 5;}return -1;}
static void draw_journey_world(void){SDL_Rect clip={0,72,960,696};SDL_SetRenderClipRect(renderer,&clip);int p=journey_plate(),k=journey_kind();
 if(p>=0){float scroll=fmodf(backgroundClock*(k==ENV_OCEAN?35:70),696);for(int n=-1;n<2;n++){nquad=0;quad(0,72+scroll+n*696,960,696,(SDL_FColor){.7f,.75f,.8f,1},(p%3)/3.0f,(p/3)/2.0f,1/3.0f,1/2.0f);float a=sideBlend*PI*.5f,w=960-264*sideBlend,h=696+264*sideBlend;for(int v=0;v<nquad*4;v++){float xx=(vertices[v].position.x-480)*w/960,yy=(vertices[v].position.y-420)*h/696;vertices[v].position.x=480+xx*cosf(a)-yy*sinf(a);vertices[v].position.y=420+xx*sinf(a)+yy*cosf(a);}float speed=k==ENV_OCEAN?35:70;lastGroundDX=-sinf(a)*backgroundClock*speed*h/696;lastGroundDY=cosf(a)*backgroundClock*speed*h/696;flush(journeyPlates);}}
 if(k==ENV_SKY||k==ENV_OCEAN||k==ENV_EM){/* Share terrain's screen-space flight vector; no separate left/down overlay. */float foreground=ex.phase==10?1000:90;SDL_SetTextureBlendMode(cloudTexture,SDL_BLENDMODE_BLEND);SDL_SetTextureColorMod(cloudTexture,190,215,235);scrolling_layer(cloudTexture,foreground,1.6f,70,1);scrolling_layer(cloudTexture,foreground*1.6f,1.15f,55,1);if(k==ENV_OCEAN){for(int i=0;i<130;i++){float x=fmodf(i*79+backgroundClock*90,960),y=72+fmodf(i*43+backgroundClock*1300,696);SDL_SetRenderDrawColor(renderer,170,210,245,100);SDL_RenderLine(renderer,x,y,x-5,y+20);}}}
 SDL_SetRenderClipRect(renderer,0);
}
