static void draw_journey_attached(void){for(int e=0;e<MAXE;e++)if(g.enemies[e].on&&g.enemies[e].dotTicks){nquad=0;quad(g.enemies[e].x/Q*3-36,g.enemies[e].y/Q*3-36,72,72,(SDL_FColor){.2f,.5f,1,.35f},0,0,1,1);flush(halo);}if(ex.repairFlash){nquad=0;quad(g.px/Q*3-70,player_y/Q*3-70,140,140,(SDL_FColor){.1f,1,.65f,ex.repairFlash/80.0f},0,0,1,1);flush(halo);}for(int i=0;i<ex.leeches;i++)journey_cell(parasiteTexture,i%2,0,3,1,parasite_x(i),parasite_y(i),11,12);if(journey_kind()==ENV_BEAST&&ex.env.timer%500>=400){int c=ex.env.timer%500;journey_rect(125,24,70,232,110,170,255,c<475?25:80);journey_line(125,24,125,256,130,220,255,170);journey_line(195,24,195,256,130,220,255,170);if(c>=475)for(int y=30;y<256;y+=16)journey_line(130+(y%7),y,190-(y%11),y+16,200,245,255,240);}}
